const fs = require("fs");
const stats = JSON.parse(fs.readFileSync("dist/apps/web/stats.json"));
const target = "chunk-4QNLBE2I.js";
const out = stats.outputs;
let key = Object.keys(out).find(k => k.endsWith(target));
if (!key) { console.error("not found"); process.exit(1); }
const o = out[key];
console.log("Total bytes:", o.bytes);
const inputs = Object.entries(o.inputs).map(([k, v]) => [k, v.bytesInOutput]).filter(([,b]) => b > 0);
inputs.sort((a, b) => b[1] - a[1]);
console.log("Top 40 contributors:");
for (const [k, b] of inputs.slice(0, 40)) {
  // Strip the long .pnpm path prefix
  const short = k.replace(/.*node_modules\/\.pnpm\/[^/]+\/node_modules\//, "").replace(/.*node_modules\//, "").replace(/^libs\//, "L:").replace(/^apps\//, "A:");
  console.log(`  ${(b/1024).toFixed(1).padStart(7)}KB  ${short}`);
}
const totalIn = inputs.reduce((s, [,b]) => s+b, 0);
console.log("Sum:", (totalIn/1024).toFixed(1), "KB across", inputs.length, "modules");
'

