            const playbackUrl = activeChannel
                ? resolveM3uCatchupUrl(activeChannel, action.program)
                : null;

            return playbackUrl
                ? EpgActions.setActivePlaybackUrl({ playbackUrl })
                : EpgActions.resetActiveEpgProgram();
        })
    );
});

