    ).map((channel) => {
        const channelId = resolveChannelEpgLookupKey(channel);
        const epgProgram = channelId ? epgMap.get(channelId) : null;
        return {
            ...channel,
            epgProgram,
            logo: resolveChannelLogo(channel, iconMap),
            progressPercentage: this.calculateProgress(epgProgram),
        } as EnrichedChannel;

