1	import { inject, Injectable } from '@angular/core';
2	import { MatSnackBar } from '@angular/material/snack-bar';
3	import { Store } from '@ngrx/store';
4	import { TranslateService } from '@ngx-translate/core';
5	import { PlaylistActions } from 'm3u-state';
6	import { DataService } from 'services';
7	import {
8	    AUTO_UPDATE_PLAYLISTS,
9	    ERROR,
10	    Playlist,
11	    PLAYLIST_PARSE_BY_URL,
12	    PLAYLIST_UPDATE,
13	    XTREAM_REQUEST,
14	    XTREAM_RESPONSE,
15	    XtreamCodeActions,
16	} from 'shared-interfaces';
17	import { AppConfig } from '../../environments/environment';
18	import {
19	    createPortalDebugRequestContext,
20	    logPortalDebugEvent,
21	} from '@iptvnator/portal/shared/util';
22	
23	interface PlayerLaunchPayload {
24	    readonly headers?: Record<string, string>;
25	    readonly origin?: string;
26	    readonly referer?: string;
27	    readonly startTime?: number;
28	    readonly thumbnail?: string;
29	    readonly title?: string;
30	    readonly url: string;
31	    readonly ['user-agent']?: string;
32	    readonly contentInfo?: unknown;
33	}
34	
35	interface ErrorStatus {
36	    readonly message?: string;
37	    readonly status?: number;
38	}
39	
40	@Injectable({
41	    providedIn: 'root',
42	})
43	export class ElectronService extends DataService {
44	    private eventListeners: { [key: string]: () => void } = {};
45	    private readonly snackBar = inject(MatSnackBar);
46	    private readonly store = inject(Store);
47	    private readonly translateService = inject(TranslateService);
48	    private readonly silentXtreamActions = new Set<string>([
49	        XtreamCodeActions.GetAccountInfo,
50	        XtreamCodeActions.GetLiveCategories,
51	        XtreamCodeActions.GetVodCategories,
52	        XtreamCodeActions.GetSeriesCategories,
53	        XtreamCodeActions.GetShortEpg,
54	        XtreamCodeActions.GetSimpleDataTable,
55	        XtreamCodeActions.GetSimpleDateTable,
56	    ]);
57	
58	    constructor() {
59	        super();
60	        console.log('Electron service initialized...');
61	        this.setupPlayerErrorListener();
62	        this.setupPortalDebugListener();
63	    }
64	
65	    private setupPlayerErrorListener() {
66	        // Listen for player errors from the backend
67	        if (window.electron?.onPlayerError) {
68	            window.electron.onPlayerError(
69	                (data: {
70	                    player: string;
71	                    error: string;
72	                    originalError: string;
73	                }) => {
74	                    console.error(`${data.player} Error:`, data.originalError);
75	                    this.snackBar.open(
76	                        `${data.player} Error: ${data.error}`,
77	                        'Close',
78	                        {
79	                            duration: 7000,
80	                            panelClass: ['error-snackbar'],
81	                        }
82	                    );
83	                }
84	            );
85	        }
86	    }
87	
88	    private setupPortalDebugListener() {
89	        const onPortalDebugEvent = (
90	            window.electron as {
91	                onPortalDebugEvent?: (
92	                    callback: (
93	                        event: Parameters<typeof logPortalDebugEvent>[0]
94	                    ) => void
95	                ) => void;
96	            }
97	        ).onPortalDebugEvent;
98	
99	        if (AppConfig.production || !onPortalDebugEvent) {
100	            return;
101	        }
102	
103	        onPortalDebugEvent((event) => {
104	            logPortalDebugEvent(
105	                event as Parameters<typeof logPortalDebugEvent>[0]
106	            );
107	        });
108	    }
109	
110	    getAppVersion(): string {
111	        return AppConfig.version;
112	    }
113	
114	    async sendIpcEvent<T = unknown>(
115	        type: string,
116	        payload?: unknown
117	    ): Promise<T> {
118	        if (type === PLAYLIST_PARSE_BY_URL) {
119	            this.fetchM3uPlaylistFromUrl(payload);
120	            return undefined as T;
121	        }
122	
123	        if (type === PLAYLIST_UPDATE) {
124	            this.updateM3uPlaylistFromFile(
125	                payload as {
126	                    id: string;
127	                    filePath?: string;
128	                    url?: string;
129	                    title: string;
130	                }
131	            );
132	            return undefined as T;
133	        }
134	
135	        if (type === XTREAM_REQUEST) {
136	            return (await this.forwardXtreamRequest(
137	                payload as { url: string; params: Record<string, string> }
138	            )) as T;
139	        }
140	
141	        if (type === 'STALKER_REQUEST') {
142	            return (await this.fetchStalkerData(
143	                payload as {
144	                    url: string;
145	                    macAddress: string;
146	                    params: Record<string, string>;
147	                }
148	            )) as T;
149	        }
150	
151	        if (type === 'OPEN_MPV_PLAYER') {
152	            const data = payload as PlayerLaunchPayload;
153	            try {
154	                return (await window.electron.openInMpv(
155	                    data.url,
156	                    data.title ?? '',
157	                    data.thumbnail ?? '',
158	                    data['user-agent'] ?? undefined,
159	                    data.referer ?? undefined,
160	                    data.origin ?? undefined,
161	                    data.contentInfo,
162	                    data.startTime,
163	                    data.headers ?? undefined
164	                )) as T;
165	            } catch (error: unknown) {
166	                const errorMessage =
167	                    this.getErrorDetails(error)?.message ?? String(error);
168	                this.snackBar.open(
169	                    `Error launching MPV: ${errorMessage}`,
170	                    'Close',
171	                    {
172	                        duration: 5000,
173	                    }
174	                );
175	                console.error('MPV launch error:', error);
176	                throw error;
177	            }
178	        }
179	
180	        if (type === 'OPEN_VLC_PLAYER') {
181	            const data = payload as PlayerLaunchPayload;
182	            try {
183	                return (await window.electron.openInVlc(
184	                    data.url,
185	                    data.title ?? '',
186	                    data.thumbnail ?? '',
187	                    data['user-agent'] ?? undefined,
188	                    data.referer ?? undefined,
189	                    data.origin ?? undefined,
190	                    data.contentInfo,
191	                    data.startTime,
192	                    data.headers ?? undefined
193	                )) as T;
194	            } catch (error: unknown) {
195	                const errorMessage =
196	                    this.getErrorDetails(error)?.message ?? String(error);
197	                this.snackBar.open(
198	                    `Error launching VLC: ${errorMessage}`,
199	                    'Close',
200	                    {
201	                        duration: 5000,
202	                    }
203	                );
204	                console.error('VLC launch error:', error);
205	                throw error;
206	            }
207	        }
208	
209	        if (type === AUTO_UPDATE_PLAYLISTS) {
210	            const data = payload as Playlist[];
211	            const playlists = await window.electron.autoUpdatePlaylists(data);
212	            this.store.dispatch(
213	                PlaylistActions.updateManyPlaylists({
214	                    playlists,
215	                })
216	            );
217	            this.snackBar.open(
218	                this.translateService.instant(
219	                    'HOME.PLAYLISTS.AUTO_REFRESH_UPDATE_SUCCESS'
220	                ),
221	                null,
222	                { duration: 2000 }
223	            );
224	            return playlists as T;
225	        }
226	
227	        console.log('Unknown type', type);
228	        return undefined as T;
229	    }
230	
231	    private async fetchStalkerData(payload: {
232	        url: string;
233	        macAddress: string;
234	        params: Record<string, string>;
235	        requestId?: string;
236	        token?: string;
237	        serialNumber?: string;
238	    }) {
239	        const context = createPortalDebugRequestContext({
240	            provider: 'stalker',
241	            operation: payload.params?.action ?? 'unknown',
242	            transport: 'electron-renderer',
243	            request: payload,
244	        });
245	
246	        try {
247	            // Use Electron IPC to make the Stalker request
248	            const response = await window.electron.stalkerRequest({
249	                ...payload,
250	                requestId: context.requestId,
251	            });
252	            return response;
253	        } catch (err: unknown) {
254	            const errorInfo = this.getErrorDetails(err);
255	            console.error('Stalker request error:', err);
256	            this.snackBar.open(
257	                `Error: ${errorInfo?.message ?? ' Not found'}, status: ${errorInfo?.status ?? 404}`,
258	                'Close',
259	                {
260	                    duration: 5000,
261	                }
262	            );
263	            throw err;
264	        }
265	    }
266	
267	    private async fetchM3uPlaylistFromUrl(payload: Partial<Playlist>) {
268	        const title = payload.title?.trim() || undefined;
269	
270	        window.electron
271	            .fetchPlaylistByUrl(payload.url, title)
272	            .then((result) => {
273	                this.store.dispatch(
274	                    PlaylistActions.handleAddingPlaylistByUrl({
275	                        isTemporary: !!payload?.isTemporary,
276	                        playlist: result,
277	                    })
278	                );
279	            })
280	            .catch((error: unknown) => {
281	                const statusCode = this.extractHttpStatusCode(error);
282	                let messageKey = 'HOME.URL_UPLOAD.ERROR_FETCH_FAILED';
283	                if (statusCode === 403) {
284	                    messageKey = 'HOME.URL_UPLOAD.ERROR_403';
285	                } else if (statusCode === 404) {
286	                    messageKey = 'HOME.URL_UPLOAD.ERROR_404';
287	                } else if (statusCode === 401) {
288	                    messageKey = 'HOME.URL_UPLOAD.ERROR_401';
289	                }
290	                this.snackBar.open(
291	                    this.translateService.instant(messageKey),
292	                    this.translateService.instant('CLOSE'),
293	                    { duration: 5000 }
294	                );
295	            });
296	    }
297	
298	    private extractHttpStatusCode(error: unknown): number | null {
299	        if (
300	            error &&
301	            typeof error === 'object' &&
302	            'response' in error &&
303	            error.response &&
304	            typeof error.response === 'object' &&
305	            'status' in error.response
306	        ) {
307	            return error.response.status as number;
308	        }
309	        // Parse status from error message string (IPC serialization)
310	        const msg = String((error as { message?: string })?.message ?? error);
311	        const match = msg.match(/status code (\d{3})/);
312	        return match ? parseInt(match[1], 10) : null;
313	    }
314	
315	    private async updateM3uPlaylistFromFile(data: {
316	        id: string;
317	        url?: string;
318	        filePath?: string;
319	        title: string;
320	    }) {
321	        try {
322	            let playlistObject: Playlist;
323	            if (data.url && !data.filePath) {
324	                playlistObject = await window.electron.fetchPlaylistByUrl(
325	                    data.url,
326	                    data.title
327	                );
328	            } else if (data.filePath && !data.url) {
329	                playlistObject =
330	                    await window.electron.updatePlaylistFromFilePath(
331	                        data.filePath,
332	                        data.title
333	                    );
334	            } else {
335	                console.error(
336	                    'Either url or filePath must be provided, but not both.'
337	                );
338	                return;
339	            }
340	
341	            this.store.dispatch(
342	                PlaylistActions.updatePlaylist({
343	                    playlist: {
344	                        ...playlistObject,
345	                        _id: data.id,
346	                    },
347	                    playlistId: data.id,
348	                })
349	            );
350	
351	            this.snackBar.open(
352	                this.translateService.instant(
353	                    'HOME.PLAYLISTS.PLAYLIST_UPDATE_SUCCESS'
354	                ),
355	                null,
356	                { duration: 2000 }
357	            );
358	        } catch (error: unknown) {
359	            console.error('Playlist refresh error:', error);
360	            this.snackBar.open(
361	                this.getPlaylistRefreshErrorMessage(error, data),
362	                this.translateService.instant('CLOSE'),
363	                { duration: 5000 }
364	            );
365	        }
366	    }
367	
368	    private getPlaylistRefreshErrorMessage(
369	        error: unknown,
370	        data: { url?: string; filePath?: string }
371	    ): string {
372	        if (data.filePath) {
373	            const errorMessage = String(
374	                this.getErrorDetails(error)?.message ?? error ?? ''
375	            );
376	
377	            if (
378	                /(ENOENT|no such file or directory|not found)/i.test(
379	                    errorMessage
380	                )
