116	    readonly searchQuery = signal(this.readPersistedSearchQuery());
117	    readonly playlistTypeFilters = signal(this.readPersistedTypeFilters());
118	    readonly searchExpanded = signal(false);
119	    private static readonly SEARCH_AUTO_VISIBLE_THRESHOLD = 5;
120	
121	    readonly playlists = this.playlistContext.playlists;
122	    readonly allPlaylistsLoaded = this.playlistContext.allPlaylistsLoaded;
123	    readonly activePlaylistId = this.playlistContext.resolvedPlaylistId;
124	    readonly activePlaylist = this.playlistContext.activePlaylist;
125	    readonly filteredPlaylists = computed(() => {
126	        const query = this.searchQuery().toLowerCase().trim();
127	        const filters = this.playlistTypeFilters();
128	        const allPlaylists = this.playlists();
129	        const filteredByType = allPlaylists.filter((playlist) => {
130	            const playlistType = this.getPlaylistFilterType(playlist);
131	            return filters[playlistType];
132	        });
133	        const filtered = query
134	            ? filteredByType.filter(
135	                  (playlist) =>
136	                      playlist.title?.toLowerCase().includes(query) ||
137	                      playlist.filename?.toLowerCase().includes(query)
138	              )
139	            : filteredByType;
140	
141	        return [...filtered].sort(
142	            (a, b) =>
143	                new Date(b.importDate ?? 0).getTime() -
144	                new Date(a.importDate ?? 0).getTime()
145	        );
146	    });
147	    readonly displayTitle = computed(() => {
148	        if (!this.activePlaylistId()) {
149	            return 'Select playlist';
150	        }
151	
152	        return (
153	            this.currentTitle() ||
154	            this.activePlaylist()?.title ||
155	            this.activePlaylist()?.filename ||
156	            this.activePlaylist()?.url ||
157	            this.activePlaylist()?.portalUrl ||
158	            'Untitled playlist'
159	        );
160	    });
161	
162	    readonly availablePlaylistTypes = computed(() => {
163	        const types = new Set<PlaylistFilterType>();
164	        for (const playlist of this.playlists()) {
165	            types.add(this.getPlaylistFilterType(playlist));
166	        }
167	        return types;
168	    });
169	    readonly showTypeFilters = computed(
170	        () => this.availablePlaylistTypes().size > 1
171	    );
