191	            this.clearMenuOverlayWidth();
192	            this.clearSearchFocusTimeout();
193	        });
194	    }
195	
196	    onMenuOpened(): void {
197	        this.isMenuOpen.set(true);
198	        this.syncMenuOverlayWidthToTrigger();
199	        if (this.showSearchField()) {
200	            this.focusSearchField();
201	        }
202	        void this.checkPortalStatuses(this.playlists());
