        }

        const response =
            await this.dataService.sendIpcEvent<XtreamPortalStatusResponse>(
                'XTREAM_REQUEST',
                {
                    url: normalizedUrl,
                    params: {
                        password,
                        username,
                        action: 'get_account_info',
