        if (payload.user_info.status === 'Active') {
            if (!payload.user_info.exp_date) {
                return 'active';
            }

            const expDate = new Date(
                parseInt(payload.user_info.exp_date, 10) * 1000
            );
            return expDate < new Date() ? 'expired' : 'active';
