127	function buildFallbackBackground(
128	    title: string,
129	    saturationA: number,
130	    lightnessA: number,
131	    saturationB: number,
132	    lightnessB: number,
133	    hueOffset: number
134	): string {
135	    const hue = calculateHue(title || 'placeholder');
136	    const h2 = (hue + hueOffset) % 360;
137	    return `linear-gradient(135deg, hsl(${hue}, ${saturationA}%, ${lightnessA}%) 0%, hsl(${h2}, ${saturationB}%, ${lightnessB}%) 100%)`;
