753	    private async loadM3uPlaylistFavorites(
754	        playlistMeta: PlaylistMeta
755	    ): Promise<DashboardFavoriteItem[]> {
756	        const playlist = (await firstValueFrom(
757	            this.playlistsService.getPlaylistById(playlistMeta._id)
758	        )) as Playlist & {
759	            playlist?: {
760	                items?: Channel[];
761	            };
762	        };
763	        const favorites = Array.isArray(playlist?.favorites)
764	            ? playlist.favorites.filter(
765	                  (favorite): favorite is string =>
766	                      typeof favorite === 'string' && favorite.trim().length > 0
767	              )
768	            : [];
769	
770	        if (favorites.length === 0) {
771	            return [];
772	        }
773	
774	        const items: Channel[] = Array.isArray(playlist?.playlist?.items)
775	            ? (playlist.playlist.items as Channel[])
776	            : [];
777	        const fallbackTimestamp =
778	            this.getM3uFavoriteTimestamp(playlistMeta) ??
779	            new Date(0).toISOString();
780	        const favoritePositions = new Map<string, number>();
781	
782	        favorites.forEach((favorite, index) => {
783	            if (!favoritePositions.has(favorite)) {
784	                favoritePositions.set(favorite, index);
785	            }
786	        });
787	
788	        return items.reduce<DashboardFavoriteItem[]>((acc, channel) => {
789	            const channelId = String(channel.id ?? '').trim();
790	            const channelUrl = String(channel.url ?? '').trim();
791	            const channelIdFavoritePosition = favoritePositions.get(channelId);
792	            const channelUrlFavoritePosition =
793	                favoritePositions.get(channelUrl);
794	            const matchedFavoriteId =
795	                channelIdFavoritePosition !== undefined &&
796	                (channelUrlFavoritePosition === undefined ||
797	                    channelIdFavoritePosition <= channelUrlFavoritePosition)
798	                    ? channelId
799	                    : channelUrlFavoritePosition !== undefined
800	                      ? channelUrl
801	                      : null;
802	
803	            if (!matchedFavoriteId) {
804	                return acc;
805	            }
806	
807	            acc.push({
808	                id: matchedFavoriteId,
809	                title: channel.name?.trim() || channel.tvg?.name || channelId,
810	                type: 'live',
811	                playlist_id: playlistMeta._id,
812	                playlist_name:
813	                    playlistMeta.title || playlistMeta.filename || 'M3U',
814	                added_at: fallbackTimestamp,
815	                category_id: 'live',
816	                xtream_id: matchedFavoriteId,
817	                poster_url: channel.tvg?.logo || undefined,
818	                source: 'm3u',
819	            });
820	            return acc;
821	        }, []);
822	    }
823	
824	    private getM3uFavoriteTimestamp(playlist: PlaylistMeta): string | null {
825	        if (playlist.updateDate) {
826	            return new Date(playlist.updateDate).toISOString();
827	        }
828	
829	        return typeof playlist.importDate === 'string'
830	            ? playlist.importDate
831	            : null;
832	    }
833	
834	    private getPlaylistActivityTimestamp(item: PlaylistMeta): number {
835	        return this.recentPlaylistActivityTimestamps().get(item._id) ?? 0;
836	    }
837	
838	    private getRecentTimestamp(item: PlaylistMeta): number {
839	        return toTimestamp(item.updateDate) || toTimestamp(item.importDate);
840	    }
