169	    async save(): Promise<void> {
170	        this.isSaving.set(true);
171	        try {
172	            const categories = this.categories();
173	            const toHide = categories.filter((c) => !c.selected).map((c) => c.id);
174	            const toShow = categories.filter((c) => c.selected).map((c) => c.id);
175	
176	            if (toHide.length > 0) {
177	                await this.dbService.updateCategoryVisibility(toHide, true);
178	            }
179	            if (toShow.length > 0) {
180	                await this.dbService.updateCategoryVisibility(toShow, false);
181	            }
182	
183	            this.dialogRef.close(true);
184	        } catch (error) {
