46	function parseDuration(duration: string | number | undefined): number {
47	    if (!duration) {
48	        return 0;
49	    }
50	
51	    if (typeof duration === 'number') {
52	        return duration;
53	    }
54	
55	    const parts = duration.split(':').map(Number);
56	    if (parts.length === 3) {
57	        return parts[0] * 3600 + parts[1] * 60 + parts[2];
58	    }
59	    if (parts.length === 2) {
60	        return parts[0] * 60 + parts[1];
61	    }
62	
63	    return Number(duration) || 0;
64	}
